import Foundation
import RingProtocol

/// A paired ring as the app knows it. Deliberately holds no advertised name, Bluetooth address or
/// serial number: `id` is generated by the app, and the rest is what the ring reports about itself.
public struct StoredRing: Equatable, Sendable {
    public var id: UUID
    /// Protocol family, for example `ycbt`.
    public var protocolFamily: String
    public var model: String?
    public var firmware: String?
    /// Whole milliseconds.
    public var firstSeenAt: Date
    /// What CoreBluetooth calls this ring on this phone (`CBPeripheral.identifier`), used to
    /// reconnect without scanning; `nil` until the app has connected. Meaningless off this device:
    /// not the Bluetooth address, never to be exported or sent anywhere. Set with
    /// `RingStore.setPeripheralIdentifier(_:forRing:)`.
    public var peripheralIdentifier: UUID? = nil
}

/// A history transfer as saved, with its row id and owning ring.
public struct StoredTransfer: Equatable, Sendable {
    public var id: Int64
    public var ringID: UUID
    public var transfer: HistoryTransfer
}

/// A record of one fetch: when, how long its data was, under which zone, and the content hash of
/// that data. It stays whether or not the transfer row still exists (pruning deletes the row, a
/// duplicate never had one of its own). The data itself is in a surviving transfer that starts
/// with it.
public struct TransferObservation: Equatable, Sendable {
    public var id: Int64
    public var ringID: UUID
    public var kind: HistoryKind
    public var dataLength: Int
    public var header: [UInt8]
    /// `RingStore.contentHash` of the observed data, the same value a stored transfer carries.
    public var contentHash: [UInt8]
    /// Whole milliseconds.
    public var fetchedAt: Date
    public var timeZoneIdentifier: String
}

/// The result of listing transfers.
public struct TransferListing: Equatable, Sendable {
    public var transfers: [StoredTransfer]
    /// Rows left out because their kind code is unknown to this version of the app.
    public var skippedUnknownKind: Int
}

/// The fetch log listing, with the rows this version could not read counted rather than hidden.
public struct ObservationListing: Equatable, Sendable {
    public var observations: [TransferObservation]
    /// Rows left out because their kind code is unknown to this version of the app.
    public var skippedUnknownKind: Int
}

public enum InsertOutcome: Equatable, Sendable {
    /// A new row was written. `pruned` earlier rows (same ring and kind, data a strict prefix of
    /// this one's) were deleted in the same transaction; 0 when none were superseded.
    case inserted(id: Int64, pruned: Int)
    /// The same ring, kind and data bytes were already stored; the first row was kept.
    case duplicate(existingID: Int64)
    /// Nothing was stored: the data is a strict prefix of a longer stored transfer (`existingID`)
    /// for the same ring and kind, so it holds no record that one lacks.
    case supersededByExisting(existingID: Int64)
}

/// One time the app set the ring's clock. The ring stamps records with whatever clock was last
/// set and does not follow travel or daylight saving, so ingestion needs the offset that was in
/// force when a record was stamped.
public struct ClockSetEvent: Equatable, Sendable {
    public var ringID: UUID
    /// The instant the clock was set. Whole milliseconds.
    public var instant: Date
    public var timeZoneIdentifier: String
    /// The UTC offset in seconds that was sent to the ring.
    public var utcOffsetSeconds: Int

    public init(ringID: UUID, instant: Date, timeZoneIdentifier: String, utcOffsetSeconds: Int) {
        self.ringID = ringID
        self.instant = instant
        self.timeZoneIdentifier = timeZoneIdentifier
        self.utcOffsetSeconds = utcOffsetSeconds
    }
}

public enum RingStoreError: Error, Equatable, Sendable {
    case unknownRing(UUID)
    /// The database file (or its -wal/-shm companion) could not be created or its mode set.
    case fileAccess(path: String, errno: Int32)
    /// A stored value could not be read back (for example an unknown history kind name).
    case corruptRow(String)
    /// `ingest` does not handle this kind (the combined record is tracked separately).
    case notIngestible(HistoryKind)
}
